  useEffect(() => { document.documentElement.style.setProperty('--user-font-scale', String(Number(fontScale) / 100)); document.documentElement.dataset.fontStyle = fontStyle; document.documentElement.dataset.cardRoundness = cardRoundness; document.documentElement.dataset.interfaceDensity = interfaceDensity; localStorage.setItem('advocate-font-scale', fontScale); localStorage.setItem('advocate-font-style', fontStyle); localStorage.setItem('advocate-card-roundness', cardRoundness); localStorage.setItem('advocate-interface-density', interfaceDensity); }, [fontScale, fontStyle, cardRoundness, interfaceDensity]);
